#!/usr/bin/env python3
"""Reviewed consolidated TimeLapse Pro requirements -> GRC (121 items)."""
from __future__ import annotations
import base64,json,re,sys,zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/"headend"))
from database import GrcEvidence,GrcItem,GrcLink,SessionLocal
ACTOR="chatgpt-reviewed-requirements-20260919"
SOURCE_URI="artifact://TimeLapse_Pro_Komplet_Krav_og_Gap_Register_2026-09-19.docx"
ROWS=json.loads(zlib.decompress(base64.b64decode("")).decode())
def norm(s): return re.sub(r"[^a-z0-9æøå]+"," ",(s or "").casefold()).strip()
def main():
 db=SessionLocal();created=updated=linked=0
 try:
  existing=db.query(GrcItem).filter_by(item_type="requirement").all();exact={}
  for c in existing:
   if c.status=="candidate_review": exact.setdefault(norm(c.description or c.title),[]).append(c)
  for row in ROWS:
   rid=row["external_id"];item=db.query(GrcItem).filter_by(item_type="requirement",external_id=rid).first()
   attrs={k:row[k] for k in ("category","requirement_kind","implementation_status","current_evidence_summary","gap_next_step","source_rationale")}
   attrs.update({"reviewed_baseline":"2026-09-19","decision_state":"reviewed","provenance_policy":"Knowledge Archaeology consolidated register; absence does not kill requirement"})
   if item is None:
    item=GrcItem(item_type="requirement",external_id=rid,title=f'{rid}: {row["description"]}'[:300],description=row["description"],status="active",priority=row["priority"].lower(),source="reviewed-requirements-20260919",scope={"product":"timelapse-pro","category":row["category"]},attributes=attrs,created_by=ACTOR,updated_by=ACTOR);db.add(item);db.flush();created+=1
   else:
    item.title=f'{rid}: {row["description"]}'[:300];item.description=row["description"];item.status="active";item.priority=row["priority"].lower();item.source="reviewed-requirements-20260919";item.scope={"product":"timelapse-pro","category":row["category"]};item.attributes=attrs;item.updated_by=ACTOR;updated+=1
   uri=SOURCE_URI+"#"+rid
   if db.query(GrcEvidence).filter_by(item_id=item.id,uri=uri).first() is None:
    db.add(GrcEvidence(item_id=item.id,evidence_type="requirement_source",title="Reviewed consolidated requirement baseline",uri=uri,content={"source_rationale":row["source_rationale"],"status_at_review":row["implementation_status"],"evidence_summary":row["current_evidence_summary"]},collected_by=ACTOR,retention_class="grc_source_permanent"))
   for old in exact.get(norm(row["description"]),[]):
    if old.id==item.id: continue
    if db.query(GrcLink).filter_by(source_item_id=old.id,target_item_id=item.id,relationship="superseded_by_reviewed_requirement").first() is None:
     db.add(GrcLink(source_item_id=old.id,target_item_id=item.id,relationship="superseded_by_reviewed_requirement",rationale="Exact normalized text match to reviewed 2026-09-19 requirement",created_by=ACTOR));linked+=1
    old.status="superseded";oa=dict(old.attributes or {});oa["superseded_by_external_id"]=rid;oa["supersession_basis"]="exact_normalized_text_match";old.attributes=oa;old.updated_by=ACTOR
  db.commit();ids=[r["external_id"] for r in ROWS];got=db.query(GrcItem).filter(GrcItem.item_type=="requirement",GrcItem.external_id.in_(ids)).all();active=sum(x.status=="active" for x in got)
  print(json.dumps({"baseline":len(ROWS),"created":created,"updated":updated,"exact_candidate_links":linked,"read_back":len(got),"active_read_back":active},ensure_ascii=False))
  if len(got)!=len(ROWS) or active!=len(ROWS): raise SystemExit("GRC read-back failed")
 except Exception: db.rollback();raise
 finally: db.close()
if __name__=="__main__": main()
